input.command:
mkdir -p src && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");

  // --- Quote: base premiums per main item type ---
  it.todo("quotes a single sword as 100 G base premium (+10 G first insurance, +5 G fee = 115 G)");
  it.todo("quotes a single amulet as 60 G base premium (+6 G first insurance, +5 G fee = 71 G)");
  it.todo("quotes a single staff as 80 G base premium (+8 G first insurance, +5 G fee = 93 G)");
  it.todo("quotes a single potion as 40 G base premium (+4 G first insurance, +5 G fee = 49 G)");
  it.todo("quotes a single rune as 25 G base premium (+2.5 G first insurance, +5 G fee = 33 G after rounding up)");
  it.todo("quotes a single moonstone as 25 G base premium (+2.5 G first insurance, +5 G fee = 33 G after rounding up)");

  // --- Quote: component building block of 3 alike components ---
  it.todo("quotes 2 runes as 50 G base premium (no block)");
  it.todo("quotes 3 runes as 60 G base premium (block applies)");
  it.todo("quotes 4 runes as 100 G base premium (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as 175 G base premium (no block -- 7 is not a multiple forming exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone as 75 G base premium (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones as 120 G base premium (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50% curse surcharge to the cursed item's base premium (cursed sword: 100 G base + 50 G curse)");
  it.todo("adds a 30% high-enchantment surcharge at enchantment exactly 5 (sword: 100 G base + 30 G)");
  it.todo("adds no high-enchantment surcharge at enchantment 4 (sword: 100 G base only)");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment exactly 5 (100 G + 50 G + 30 G)");
  it.todo("applies item-specific curse surcharge only to the cursed item, not the policy total: cursed sword + plain amulet -> 160 G base + 50 G curse = 210 G before further modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10% first-insurance surcharge on the policy base premium");
  it.todo("applies a 15% follow-up discount on every contract after the customer's first quote in the scenario");
  it.todo("applies the first-insurance surcharge on a follow-up contract too (each quoted item is a first insurance)");
  it.todo("adds the 5 G processing fee at the very end of every quote");

  // --- Quote: rounding in MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts fractional and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, no previous contract) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed steel sword (enchantment 7) as 160 G");

  // --- Quote: errors ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick) by throwing an Error");

  // --- Insurance sum and cap ---
  it.todo("computes insurance sum 1600 G and cap 3200 G for a policy covering a sword and an amulet");
  it.todo("computes insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("computes insurance sum 1750 G and cap 3500 G for a sword and 3 runes (block affects premium only)");
  it.todo("bases the cap on the unmodified insurance value: a cursed sword has cap 2000 G even though its premium is 165 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays 400 G for 500 G damage to a regular steel sword with enchantment 3 (full reimbursement minus 100 G deductible)");
  it.todo("pays 100 G for 200 G damage to a rune (no enchantment level or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G damage -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50%: dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses dragon-material damage fully: dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("lets the 50% high-enchantment rule win over full dragon reimbursement: dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies the 50% high-enchantment rule to a steel sword with enchantment 9: damage 1000 G -> payout 400 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damage entry of the same item type as a separate damage with its own deductible (two swords damaged)");
  it.todo("rejects a claim with more damage entries of a type than the policy covers by throwing an Error");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays 1400 G and leaves 600 G remaining cap for a 1500 G claim on a sword policy (cap 2000 G)");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remaining cap 0 G");

  // --- Claim: rounding in MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Claim: errors ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim whose damaged item has an unknown type by throwing an Error");
  it.todo("rejects a claim containing a damage entry with a negative amount (-200) by throwing an Error");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout for the schema example");
  it.todo("CLI resolves a claim's policy field as the zero-based index of the earlier quote step");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for a claim against an uninsured item");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for a negative damage amount");
});
EOF
pnpm test 2>&1 | tail -12

