input.command:
cat > src/quote.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

export function quote(
  customer: Customer,
  items: Item[],
  previousQuoteCount: number,
): number {
  const policyBasePremium = items.reduce(
    (total, item) => total + BASE_PREMIUMS[item.type],
    0,
  );
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}
EOF
