export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;

function basePremiumOf(item: Item): number {
  return COMPONENT_TYPES.includes(item.type)
    ? COMPONENT_BASE_PREMIUM
    : MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function policyBasePremiumOf(items: Item[]): number {
  return items.reduce((total, item) => total + basePremiumOf(item), 0);
}

function roundPremiumInMHPCOsFavour(amount: number): number {
  return Math.ceil(amount);
}

export function quote(
  customer: Customer,
  items: Item[],
  previousQuoteCount: number,
): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premiumBeforeFee = policyBasePremium + firstInsuranceSurcharge;
  return roundPremiumInMHPCOsFavour(premiumBeforeFee + PROCESSING_FEE);
}
