export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function countsPerAlikeGroup(components: Item[]): number[] {
  const counts = new Map<string, number>();
  for (const component of components) {
    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
  }
  return [...counts.values()];
}

function alikeComponentsBasePremiumOf(count: number): number {
  return count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremiumOf(components: Item[]): number {
  return countsPerAlikeGroup(components).reduce(
    (total, count) => total + alikeComponentsBasePremiumOf(count),
    0,
  );
}

function mainItemsBasePremiumOf(mainItems: Item[]): number {
  return mainItems.reduce(
    (total, item) => total + MAIN_ITEM_BASE_PREMIUMS[item.type],
    0,
  );
}

function policyBasePremiumOf(items: Item[]): number {
  return (
    mainItemsBasePremiumOf(items.filter((item) => !isComponent(item))) +
    componentsBasePremiumOf(items.filter(isComponent))
  );
}

function roundPremiumInMHPCOsFavour(amount: number): number {
  return Math.ceil(amount);
}

function policyModifiersOf(policyBasePremium: number): number {
  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

export function quote(
  customer: Customer,
  items: Item[],
  previousQuoteCount: number,
): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const premiumBeforeFee =
    policyBasePremium + policyModifiersOf(policyBasePremium);
  return roundPremiumInMHPCOsFavour(premiumBeforeFee + PROCESSING_FEE);
}

