function firstInsuranceSurchargeOf(policyBasePremium: number): number {
  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscountOf(
  customer: Customer,
  policyBasePremium: number,
): number {
  return isLongStandingCustomer(customer)
    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
    : 0;
}

// Policy-wide modifiers apply to the policy base premium (the sum of all
// item base premiums), in contrast to the item-specific risk surcharges.
function policyWideModifiersOf(
  customer: Customer,
  policyBasePremium: number,
): number {
  return (
    firstInsuranceSurchargeOf(policyBasePremium) -
    loyaltyDiscountOf(customer, policyBasePremium)
  );
}

export function quote(
  customer: Customer,
  items: Item[],
  previousQuoteCount: number,
): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const premium =
    policyBasePremium +
    itemRiskSurchargesOf(items) +
    policyWideModifiersOf(customer, policyBasePremium) +
    PROCESSING_FEE;
  return roundPremiumInMHPCOsFavour(premium);
}

