content.content:
import type { Item } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

// A deductible of 100 G applies per damage event, that is, once per
// damaged item rather than once per incident.
const DEDUCTIBLE_PER_DAMAGE = 100;

// How much of a damage the office reimburses before its deductible. Special
// clauses keyed on the damaged item's enchantment level and material reduce or
// restore this share; absent any clause, damage is reimbursed in full.
function reimbursementOf(damage: Damage): number {
  return damage.amount;
}

// What the office actually pays for a single damage: its reimbursement, less
// the deductible it withholds from every damage event.
function payoutFor(damage: Damage): number {
  return reimbursementOf(damage) - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(
  items: Item[],
  remainingCap: number,
  incident: Incident,
): ClaimResult {
  const payout = incident.damages.reduce(
    (total, damage) => total + payoutFor(damage),
    0,
  );
  return { payout, remainingCap: remainingCap - payout };
}

