import type { Item } from "./price-list.js";
import { coveredItemOf } from "./policy.js";
import { reimbursementShareOf } from "./reimbursement.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

// A deductible of 100 G applies per damage event, that is, once per
// damaged item rather than once per incident.
const DEDUCTIBLE_PER_DAMAGE = 100;

// What the office pays for a single damage to a known covered item: the
// reimbursable share of the damage amount, less the deductible it withholds
// from every damage event. Which item the report refers to is settled before
// this point, so the valuation turns on the item itself, never on the policy.
function payoutFor(damagedItem: Item, amount: number): number {
  return amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
}

// Settling an incident: each reported damage is matched to the covered item it
// refers to, and every match is valued and paid separately.
export function claim(
  items: Item[],
  remainingCap: number,
  incident: Incident,
): ClaimResult {
  const payout = incident.damages.reduce(
    (total, damage) =>
      total + payoutFor(coveredItemOf(items, damage.itemType), damage.amount),
    0,
  );
  return { payout, remainingCap: remainingCap - payout };
}
=====POLICY=====
import { insuranceValueOf, type Item } from "./price-list.js";

// The MHPCO caps the total payout per policy at twice the insurance sum.
const PAYOUT_CAP_MULTIPLE = 2;

export function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

export function capOf(items: Item[]): number {
  return insuranceSumOf(items) * PAYOUT_CAP_MULTIPLE;
}

// Which item of the policy a damage report refers to. The office only settles
// damage to items it actually covers, so a type outside the policy is not a
// smaller payout but a claim it refuses.
export function coveredItemOf(items: Item[], itemType: string): Item {
  const coveredItem = items.find((item) => item.type === itemType);
  if (coveredItem === undefined) {
    throw new Error(`The policy does not cover an item of type "${itemType}"`);
  }
  return coveredItem;
}

