import { readFileSync } from "node:fs";
import { claim, type Incident } from "./claim.js";
import { capOf } from "./policy.js";
import type { Item } from "./price-list.js";
import { quote, type Customer } from "./quote.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

type Result = { premium: number } | { payout: number; remainingCap: number };

interface Policy {
  items: Item[];
  remainingCap: number;
}

// The office works through a scenario's steps in order: each quote creates a
// policy a later claim can draw on, and each claim leaves that policy with
// less cap for the next one.
function resultsFor(scenario: Scenario): Result[] {
  const policies = new Map<number, Policy>();
  let quoteCount = 0;

  return scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, quoteCount);
      quoteCount += 1;
      policies.set(stepIndex, {
        items: step.items,
        remainingCap: capOf(step.items),
      });
      return { premium };
    }

    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`Step ${step.policy} did not create a policy to claim on`);
    }
    const settlement = claim(policy.items, policy.remainingCap, step.incident);
    policy.remainingCap = settlement.remainingCap;
    return settlement;
  });
}

function main(): void {
  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
  process.stdout.write(JSON.stringify({ results: resultsFor(scenario) }));
}

try {
  main();
} catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exit(1);
}
EOF
